function preventScreenshots(){document.addEventListener("keyup",e=>{e.key==="PrintScreen"&&(blurScreen(),showToast("Screenshots are disabled on this page."))}),document.addEventListener("copy",e=>{e.preventDefault(),showToast("Copying content is restricted on this page.")}),document.addEventListener("contextmenu",e=>e.preventDefault()),document.addEventListener("touchstart",()=>{this.touchTimer=setTimeout(()=>{blurScreen(),showToast("Screenshots are disabled on this page.")},1e3)}),document.addEventListener("touchend",()=>{clearTimeout(this.touchTimer)})}function blurScreen(){document.body.style.filter="blur(15px)",setTimeout(()=>{document.body.style.filter="none"},15e3)}function showToast(e){console.log(e)}preventScreenshots();
